# Let's fix the SctpChunkType enum and decoding in SctpElement to strictly use standard RFC4960 IDs instead of .ordinal
sed -i 's/enum class SctpChunkType { DATA, INIT, INIT_ACK, SACK, HEARTBEAT, COOKIE_ECHO, COOKIE_ACK, SHUTDOWN, SHUTDOWN_ACK, SHUTDOWN_COMPLETE }/enum class SctpChunkType(val code: Byte) {\n    DATA(0),\n    INIT(1),\n    INIT_ACK(2),\n    SACK(3),\n    HEARTBEAT(4),\n    HEARTBEAT_ACK(5),\n    ABORT(6),\n    SHUTDOWN(7),\n    SHUTDOWN_ACK(8),\n    ERROR(9),\n    COOKIE_ECHO(10),\n    COOKIE_ACK(11),\n    ECNE(12),\n    CWR(13),\n    SHUTDOWN_COMPLETE(14);\n\n    companion object {\n        fun fromCode(code: Byte): SctpChunkType? = values().firstOrNull { it.code == code }\n    }\n}/g' src/commonMain/kotlin/borg/trikeshed/context/sctp/SctpElement.kt
